args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?father ?fatherLabel ?deathPlaceRes ?deathPlaceResLabel ?deathPlaceLiteral ?placeDiedLiteral WHERE {
  VALUES ?p { dbp:father dbo:father dbp:parent dbo:parent dbp:parents dbo:parents dbp:fatherLink }
  <http://dbpedia.org/resource/Edward_of_Norwich,_2nd_Duke_of_York> ?p ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(lang(?fatherLabel)='en') }
  OPTIONAL { ?father dbo:deathPlace ?deathPlaceRes . OPTIONAL { ?deathPlaceRes rdfs:label ?deathPlaceResLabel FILTER(lang(?deathPlaceResLabel)='en') } }
  OPTIONAL { ?father dbp:deathPlace ?deathPlaceLiteral }
  OPTIONAL { ?father dbp:placeDied ?placeDiedLiteral }
}
LIMIT 50

